def calculate_patient_charges(patient_id, services, insurance_provider):
    total_charge = 0
    admin_fee = 0

    for service in services:
        base_cost = service['cost']

        if insurance_provider == 'BlueCross':
            if base_cost > 500:
                admin_fee += base_cost
            else:
                total_charge += base_cost
        elif insurance_provider == 'Aetna':
            admin_fee = 15
            if service['type'] != 'emergency':
                total_charge += base_cost
        else:
            total_charge += base_cost

    total_charge += admin_fee
    return total_charge
